import{_ as t,o,c as a,a2 as n}from"./chunks/framework.CWWEQfK7.js";const m=JSON.parse('{"title":"Read this before contributing","description":"Learn the boundaries between six repositories, the recommended change order, and the checks required before handoff.","frontmatter":{"page_id":"development-index","title":"Read this before contributing","description":"Learn the boundaries between six repositories, the recommended change order, and the checks required before handoff."},"headers":[],"relativePath":"en/development/index.md","filePath":"en/development/index.md","lastUpdated":1786627803000}'),r={name:"en/development/index.md"};function i(d,e,s,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="read-this-before-contributing" tabindex="-1">Read this before contributing <a class="header-anchor" href="#read-this-before-contributing" aria-label="Permalink to &quot;Read this before contributing&quot;">​</a></h1><p>Ershu business code is split into five modules. A sixth composition repository, also named <code>ershu</code>, provides local integration, infrastructure, and cross-module acceptance checks. Before changing code, identify the module that owns the behavior and open only the boundaries the change needs.</p><h2 id="what-does-each-repository-own" tabindex="-1">What does each repository own? <a class="header-anchor" href="#what-does-each-repository-own" aria-label="Permalink to &quot;What does each repository own?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repository</th><th>Owns</th><th>Does not own</th></tr></thead><tbody><tr><td><code>core</code></td><td>Data models, migrations, authorization, run state, retrieval, and shared contracts</td><td>No HTTP listener or background worker</td></tr><tr><td><code>api</code></td><td>HTTP routes, web authentication, administration, cron, and webhook entry points</td><td>Does not execute analysis jobs directly</td></tr><tr><td><code>worker</code></td><td>Claiming jobs, preparing read-only workspaces, extracting facts, and generating documents and indexes</td><td>No user-facing administration API</td></tr><tr><td><code>mcp</code></td><td>Authenticated, read-only MCP query tools</td><td>Does not change projects, repositories, or run state</td></tr><tr><td><code>frontend</code></td><td>Login, project workspace, run tracking, documents, search, graph, and administration pages</td><td>Never reads the database directly</td></tr><tr><td><code>ershu</code></td><td>Locked module combination, local infrastructure, cross-repository tests, and release boundaries</td><td>Does not copy business implementations from the five modules</td></tr></tbody></table><p>API, Worker, and MCP depend on Core, but they must not couple to one another through source imports. The frontend communicates with the API over HTTP. A change that crosses modules needs a complete acceptance check in the composition repository.</p><h2 id="recommended-order-for-a-feature-change" tabindex="-1">Recommended order for a feature change <a class="header-anchor" href="#recommended-order-for-a-feature-change" aria-label="Permalink to &quot;Recommended order for a feature change&quot;">​</a></h2><ol><li>State the external behavior and failure modes, then locate the existing contract or test.</li><li>If the change affects shared data or authorization, update Core models, services, and migrations first.</li><li>Implement the entry point in its owner: HTTP in API, analysis in Worker, read-only agent retrieval in MCP.</li><li>Use the frontend API client and handle loading, empty, error, and forbidden states.</li><li>Run the owning module&#39;s formatting, type, test, and build checks, then run the composition boundary and workflow tests.</li><li>Update only the documentation affected by the behavior and include a verification outcome.</li></ol><h2 id="common-starting-points" tabindex="-1">Common starting points <a class="header-anchor" href="#common-starting-points" aria-label="Permalink to &quot;Common starting points&quot;">​</a></h2><ul><li>To understand calls and ownership, read <a href="/en/development/architecture">Architecture and data flow</a>.</li><li>For a first setup, read <a href="/en/development/local-setup">Set up local development</a>.</li><li>To add a setting, read <a href="/en/development/configuration">Configuration flow</a>.</li><li>To add an HTTP endpoint, read <a href="/en/development/add-api">Add an API</a>.</li><li>To add a tool or analysis stage, read <a href="/en/development/extend-mcp-worker">Extend MCP and Worker</a>.</li><li>To add a page, read <a href="/en/development/frontend">Build a frontend page</a>.</li><li>Before committing, read <a href="/en/development/quality">Quality and contributions</a>.</li></ul><h2 id="minimum-bar-before-handoff" tabindex="-1">Minimum bar before handoff <a class="header-anchor" href="#minimum-bar-before-handoff" aria-label="Permalink to &quot;Minimum bar before handoff&quot;">​</a></h2><ul><li>The change lives in the module that owns the responsibility, with tests for any shared contract.</li><li>A new setting has a type, default, runtime-override decision, and useful error feedback.</li><li>A new API has authentication, authorization, input, and failure-path tests.</li><li>Long-running work remains inspectable after a browser disconnect.</li><li>Documentation describes current behavior, and any claimed command result was actually observed.</li><li>The owning repository passes its checks; cross-repository work also passes composition tests.</li></ul>',11)])])}const p=t(r,[["render",i]]);export{m as __pageData,p as default};
